import { configureToiFetch, toiFetch } from '@toi/fetch';

// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Customer {
  id: string;
  name: string;
  phone: string;
  status: string;
  email?: string;
  [key: string]: unknown;
}

export async function listRecords(reason: string): Promise<{ items: Customer[] }> {
  try {
    const response = await toiFetch("customers", '/customers', { reason });
    if (!response.ok) {
      let errorData: any = null;
      try {
        errorData = await response.json();
      } catch {
        // ignore
      }
      if (response.status === 404) {
        if (errorData?.code === 'PROJECT_NOT_FOUND' || errorData?.name === 'ToiAccessRevokedError') {
          const accessErr = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
          (accessErr as any).code = 'PROJECT_NOT_FOUND';
          (accessErr as any).status = 404;
          throw accessErr;
        }
        return { items: [] };
      }
      throw new Error(errorData?.message || `조회에 실패했습니다. (${response.status})`);
    }
    return await response.json();
  } catch (err: any) {
    if (
      err?.code === 'PROJECT_NOT_FOUND' ||
      err?.name === 'ToiAccessRevokedError' ||
      (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
      err?.message?.includes('PROJECT_NOT_FOUND')
    ) {
      const accessErr = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      (accessErr as any).code = 'PROJECT_NOT_FOUND';
      (accessErr as any).status = 404;
      throw accessErr;
    }
    throw err;
  }
}

export async function getRecord(id: string, reason: string) {
  const response = await toiFetch("customers", '/customers/' + encodeURIComponent(id), { reason });
  return response.json();
}

export async function updateStatus(id: string, status: 'active' | 'inactive' | 'suspended', reason: string) {
  const response = await toiFetch("customers", '/customers/' + encodeURIComponent(id), {
    method: 'PATCH',
    reason,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status })
  });
  return response.json();
}

import { useState } from 'react';
import { Button, TextField, Table } from '@toi/tds';
import { listRecords, Customer } from './api';

interface CustomerRow extends Record<string, unknown> {
  id: string;
  name: string;
  phone: string;
  status: string;
}

export default function App() {
  const [reason, setReason] = useState('고객 목록 조회');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasSearched, setHasSearched] = useState(false);
  const [rows, setRows] = useState<CustomerRow[]>([]);

  const handleSearch = async () => {
    const trimmed = reason.trim();
    if (trimmed.length < 5) {
      setError('조회 사유를 5자 이상 입력해 주세요.');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const data = await listRecords(trimmed);
      const items: Customer[] = Array.isArray(data) ? data : data?.items ?? [];
      const formattedRows: CustomerRow[] = items.map((item) => ({
        id: String(item.id ?? ''),
        name: String(item.name ?? ''),
        phone: String(item.phone ?? ''),
        status: String(item.status ?? ''),
      }));
      setRows(formattedRows);
      setHasSearched(true);
    } catch (err: any) {
      setError(err?.message || '고객 목록 조회 중 오류가 발생했습니다.');
    } finally {
      setLoading(false);
    }
  };

  const columns = [
    { key: 'id', header: 'ID' },
    { key: 'name', header: '이름 (name)' },
    { key: 'phone', header: '전화번호 (phone)' },
    { key: 'status', header: '상태 (status)' },
  ];

  return (
    <main style={{ padding: '32px', maxWidth: '1000px', margin: '0 auto', fontFamily: 'sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 'bold', margin: '0 0 8px 0' }}>고객 목록</h1>
        <p style={{ color: '#4a5568', margin: 0, fontSize: '14px' }}>
          고객 정보를 조회하려면 5자 이상의 조회 사유를 입력하세요.
        </p>
      </header>

      <section style={{ marginBottom: '24px' }}>
        <div style={{ display: 'flex', gap: '8px', alignItems: 'flex-end' }}>
          <div style={{ flex: 1 }}>
            <TextField
              id="reason"
              name="reason"
              label="조회 사유"
              aria-label="조회 사유"
              placeholder="조회 사유를 5자 이상 입력하세요"
              value={reason}
              onChange={(e) => {
                setReason(e.target.value);
                if (error) setError(null);
              }}
            />
          </div>
          <Button
            type="button"
            onClick={handleSearch}
            disabled={loading || reason.trim().length < 5}
          >
            조회
          </Button>
        </div>
        {reason.length > 0 && reason.trim().length < 5 && (
          <p style={{ margin: '6px 0 0 0', fontSize: '12px', color: '#e53e3e' }}>
            조회 사유는 5자 이상 입력해야 합니다.
          </p>
        )}
      </section>

      {error && (
        <div
          role="alert"
          style={{
            padding: '12px 16px',
            marginBottom: '20px',
            backgroundColor: '#fff5f5',
            border: '1px solid #feb2b2',
            borderRadius: '6px',
            color: '#c53030',
            fontSize: '14px',
            lineHeight: 1.5,
          }}
        >
          {error}
        </div>
      )}

      <section>
        <Table columns={columns} rows={rows} rowKey="id" />
        {hasSearched && !loading && !error && rows.length === 0 && (
          <p style={{ textAlign: 'center', color: '#718096', margin: '32px 0' }}>
            조회된 고객 정보가 없습니다.
          </p>
        )}
      </section>
    </main>
  );
}

