import { configureToiFetch, toiFetch } from '@toi/fetch';

// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export const ACCESS_REVOKED_MESSAGE = '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요';

export interface Customer {
  id: string;
  name: string;
  phone: string;
  status: string;
  email?: string;
  [key: string]: unknown;
}

export async function listRecords(reason: string) {
  const response = await toiFetch('customers', '/customers', { reason });
  if (!response.ok) {
    let errorData: any = null;
    try {
      errorData = await response.json();
    } catch {
      // ignore json parse error
    }
    if (response.status === 404 && errorData?.code === 'PROJECT_NOT_FOUND') {
      throw new Error(ACCESS_REVOKED_MESSAGE);
    }
    throw new Error(errorData?.message || `요청 실패 (${response.status})`);
  }
  return response.json();
}

export async function getCustomer(id: string, reason: string): Promise<Customer | null> {
  let response: Response;
  try {
    response = await toiFetch('customers', `/customers/${encodeURIComponent(id)}`, { reason });
  } catch (err: any) {
    if (
      err?.name === 'ToiAccessRevokedError' ||
      err?.code === 'PROJECT_NOT_FOUND' ||
      (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
      err?.message?.includes('PROJECT_NOT_FOUND')
    ) {
      throw new Error(ACCESS_REVOKED_MESSAGE);
    }
    throw err;
  }

  if (!response.ok) {
    let errorData: any = null;
    try {
      errorData = await response.json();
    } catch {
      // ignore json parse error
    }

    if (response.status === 404) {
      if (errorData?.code === 'PROJECT_NOT_FOUND') {
        throw new Error(ACCESS_REVOKED_MESSAGE);
      }
      // Resource 404 with a different code: show no results
      return null;
    }

    throw new Error(errorData?.message || `요청 실패 (${response.status})`);
  }

  const data = await response.json();
  if (!data) return null;
  const customer = data.customer ?? data.item ?? data;
  return customer as Customer;
}

export const getRecord = getCustomer;

export async function updateStatus(id: string, status: 'active' | 'inactive' | 'suspended', reason: string) {
  const response = await toiFetch('customers', `/customers/${encodeURIComponent(id)}`, {
    method: 'PATCH',
    reason,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  });
  if (!response.ok) {
    let errorData: any = null;
    try {
      errorData = await response.json();
    } catch {
      // ignore
    }
    if (response.status === 404 && errorData?.code === 'PROJECT_NOT_FOUND') {
      throw new Error(ACCESS_REVOKED_MESSAGE);
    }
    throw new Error(errorData?.message || `요청 실패 (${response.status})`);
  }
  return response.json();
}

