import { useState } from 'react';
import { Button, TextField, Table } from '@toi/tds';
import { listOrders, Order, REVOKED_MESSAGE } from './api';

const columns = [
  { key: 'id', header: 'id' },
  { key: 'customerId', header: 'customerId' },
  { key: 'amount', header: 'amount' },
  { key: 'status', header: 'status' },
  { key: 'createdAt', header: 'createdAt' },
];

export default function App() {
  const [reason, setReason] = useState('주문 내역 조회');
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasSearched, setHasSearched] = useState(false);

  const trimmedReason = reason.trim();
  const isReasonValid = trimmedReason.length >= 5;

  const handleSearch = async () => {
    if (!isReasonValid) {
      setError('조회 사유는 최소 5자 이상 입력해야 합니다.');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const items = await listOrders(trimmedReason);
      setOrders(items);
      setHasSearched(true);
    } catch (err: any) {
      const isRevoked =
        err?.name === 'ToiAccessRevokedError' ||
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
        err?.code === 'PROJECT_NOT_FOUND' ||
        err?.message === REVOKED_MESSAGE ||
        (typeof err?.message === 'string' && err?.message.includes('PROJECT_NOT_FOUND'));

      if (isRevoked) {
        setError(REVOKED_MESSAGE);
      } else if (err?.status === 404) {
        // Only resource 404 errors with a different code may show no results
        setOrders([]);
        setHasSearched(true);
        setError(null);
      } else {
        setError(err?.message || '주문 목록을 조회하지 못했습니다.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <main style={{ maxWidth: '1000px', margin: '0 auto', padding: '32px 16px', fontFamily: 'system-ui, sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 'bold', margin: '0 0 8px' }}>주문 목록 화면</h1>
        <p style={{ color: '#6B7280', margin: 0 }}>주문 데이터 목록을 조회하고 확인합니다.</p>
      </header>

      <section style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginBottom: '24px', backgroundColor: '#F9FAFB', padding: '16px', borderRadius: '8px', border: '1px solid #E5E7EB' }}>
        <div style={{ display: 'flex', gap: '12px', alignItems: 'flex-end', flexWrap: 'wrap' }}>
          <div style={{ flex: '1 1 300px' }}>
            <TextField
              label="조회 사유"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="조회 사유를 5자 이상 입력하세요"
            />
          </div>
          <div>
            <Button
              type="button"
              onClick={handleSearch}
              disabled={isLoading || !isReasonValid}
            >
              {isLoading ? '조회 중...' : '조회'}
            </Button>
          </div>
        </div>
        {!isReasonValid && (
          <p style={{ margin: 0, fontSize: '12px', color: '#DC2626' }}>
            조회 사유는 최소 5자 이상 입력해야 합니다.
          </p>
        )}
      </section>

      {error && (
        <div
          role="alert"
          style={{
            padding: '12px 16px',
            backgroundColor: '#FEF2F2',
            color: '#B91C1C',
            border: '1px solid #F87171',
            borderRadius: '6px',
            marginBottom: '24px',
            fontWeight: 500,
          }}
        >
          {error}
        </div>
      )}

      <section>
        <Table columns={columns} rows={orders} rowKey="id" />
        {hasSearched && orders.length === 0 && !error && (
          <p style={{ textAlign: 'center', color: '#6B7280', marginTop: '16px' }}>조회된 주문 내역이 없습니다.</p>
        )}
      </section>
    </main>
  );
}

