import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface OrderItem {
  [key: string]: unknown;
  id: string;
  amount: number;
  status: string;
  customerId?: string;
  createdAt?: string;
  note?: string;
}

export interface FetchOrdersParams {
  status?: string;
  sort?: string;
  reason: string;
}

export async function fetchOrders({ status, sort = 'amount_desc', reason }: FetchOrdersParams) {
  const params = new URLSearchParams();
  if (status && status.trim()) {
    params.set('status', status.trim());
  }
  if (sort && sort.trim()) {
    params.set('sort', sort.trim());
  }

  const query = params.toString();
  const path = `/orders${query ? `?${query}` : ''}`;

  return await toiFetch('orders', path, { reason: reason.trim() });
}

export { toiFetch };

import { useState } from 'react';
import { Button, TextField, Table } from '@toi/tds';
import { fetchOrders, OrderItem } from './api';

export default function App() {
  const [status, setStatus] = useState('paid');
  const [reason, setReason] = useState('주문 목록 조회');
  const [orders, setOrders] = useState<OrderItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [accessError, setAccessError] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [hasSearched, setHasSearched] = useState(false);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async () => {
    const trimmedReason = reason.trim();
    if (trimmedReason.length < 5) {
      setError('조회 사유를 5자 이상 입력해 주세요.');
      return;
    }

    setLoading(true);
    setError(null);
    setAccessError(null);

    try {
      const response = await fetchOrders({
        status: status.trim(),
        sort: 'amount_desc',
        reason: trimmedReason,
      });

      if (!response.ok) {
        let body: any = null;
        try {
          body = await response.json();
        } catch {
