import { configureToiFetch, toiFetch } from '@toi/fetch';

// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Order {
  id: string;
  customerId: string;
  amount: number;
  status: string;
  note: string;
  createdAt?: string;
  [key: string]: unknown;
}

export class ToiAccessRevokedError extends Error {
  readonly code = 'PROJECT_NOT_FOUND';
  constructor(message = '이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요') {
    super(message);
    this.name = 'ToiAccessRevokedError';
  }
}

export class OrderNotFoundError extends Error {
  readonly code = 'NOT_FOUND';
  constructor(message = '해당 주문을 찾을 수 없습니다.') {
    super(message);
    this.name = 'OrderNotFoundError';
  }
}

export async function getOrder(id: string, reason: string): Promise<Order> {
  const response = await toiFetch('orders', `/orders/${encodeURIComponent(id)}`, { reason });
  if (!response.ok) {
    let errData: any = null;
    try {
      errData = await response.json();
    } catch {
      // response body might not be JSON
    }

    if (response.status === 404 && (errData?.code === 'PROJECT_NOT_FOUND' || errData?.error === 'PROJECT_NOT_FOUND')) {
      throw new ToiAccessRevokedError();
    }
    if (response.status === 404) {
      throw new OrderNotFoundError(errData?.message || '해당 주문을 찾을 수 없습니다.');
    }
    throw new Error(errData?.message || `주문 조회에 실패했습니다. (HTTP ${response.status})`);
  }
  return response.json();
}

import React, { useState } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { getOrder, Order, ToiAccessRevokedError, OrderNotFoundError } from './api';

export default function App() {
  const [orderId, setOrderId] = useState<string>('O001');
  const [reason, setReason] = useState<string>('주문 O001 상세 조회');
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async () => {
    if (!isReasonValid) {
      setErrorMessage('조회 사유를 5자 이상 입력해 주세요.');
      return;
    }

    setLoading(true);
    setErrorMessage(null);

    try {
      const data = await getOrder(orderId.trim(), reason.trim());
      setOrder(data);
    } catch (err: unknown) {
      setOrder(null);
      if (err instanceof ToiAccessRevokedError) {
        setErrorMessage('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else if (err instanceof OrderNotFoundError) {
        setErrorMessage('해당 주문을 찾을 수 없습니다.');
      } else if (err instanceof Error) {
        setErrorMessage(err.message);
      } else {
        setErrorMessage('알 수 없는 오류가 발생했습니다.');
      }
    } finally {
      setLoading(false);
    }
  };

  const columns = [
    { key: 'id' as const, header: 'id' },
    { key: 'customerId' as const, header: 'customerId' },
    { key: 'amount' as const, header: 'amount' },
    { key: 'status' as const, header: 'status' },
    { key: 'note' as const, header: 'note' },
  ];

  const tableRows = order ? [order] : [];

  return (
    <main style={{ maxWidth: '960px', margin: '0 auto', padding: '32px 20px', fontFamily: 'sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 'bold', margin: 0, color: '#111827' }}>
          주문 상세 조회
        </h1>
        <p style={{ color: '#6b7280', marginTop: '6px', fontSize: '14px' }}>
          주문 O001의 상세 정보를 조회합니다.
        </p>
      </header>

      {/* Query Controls */}
      <section
        style={{
          background: '#f9fafb',
          border: '1px solid #e5e7eb',
