import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface RefundItem {
  id: string;
  orderId: string;
  amount: number;
  status: string;
  reason: string;
  [key: string]: unknown;
}

export interface RefundListResponse {
  items: RefundItem[];
}

export async function listRefunds(reason: string): Promise<RefundListResponse> {
  let response: Response;
  try {
    response = await toiFetch('refunds', '/refunds', { reason });
  } catch (err: unknown) {
    const errorObj = err as { name?: string; code?: string; status?: number };
    if (
      errorObj?.name === 'ToiAccessRevokedError' ||
      errorObj?.code === 'PROJECT_NOT_FOUND' ||
      (errorObj?.status === 404 && errorObj?.code === 'PROJECT_NOT_FOUND')
    ) {
      const accessError = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      (accessError as unknown as { code: string }).code = 'PROJECT_NOT_FOUND';
      throw accessError;
    }
    throw err;
  }

