import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Refund {
  id: string;
  orderId?: string;
  amount: number;
  reason?: string;
  status: 'requested' | 'approved' | 'rejected' | string;
  [key: string]: unknown;
}

export async function getRefund(id: string, reason: string): Promise<Refund> {
  const response = await toiFetch('refunds', `/refunds/${encodeURIComponent(id)}`, {
    reason,
  });

  if (!response.ok) {
    const errData = await response.json().catch(() => null);
    if (response.status === 404 && errData?.code === 'PROJECT_NOT_FOUND') {
      throw new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
    }
    if (response.status === 404) {
      throw new Error('해당 환불 내역을 찾을 수 없습니다.');
    }
    throw new Error(errData?.message || `환불 조회에 실패했습니다. (HTTP ${response.status})`);
  }

  return response.json();
}

export async function updateRefundStatus(
  id: string,
  status: 'requested' | 'approved' | 'rejected',
  reason: string
): Promise<Refund> {
  const response = await toiFetch('refunds', `/refunds/${encodeURIComponent(id)}`, {
    method: 'PATCH',
    reason,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  });

  if (!response.ok) {
    const errData = await response.json().catch(() => null);
    if (response.status === 404 && errData?.code === 'PROJECT_NOT_FOUND') {
      throw new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
    }
    throw new Error(errData?.message || `환불 상태 변경에 실패했습니다. (HTTP ${response.status})`);
  }

  return response.json();
}

import { useState } from 'react';
import { Button, TextField, Table, Badge } from '@toi/tds';
import { getRefund, updateRefundStatus, type Refund } from './api';

export default function App() {
  const [refundId, setRefundId] = useState('R001');
  const [reason, setReason] = useState('환불 R001 상태 확인 및 승인 처리');
  const [refund, setRefund] = useState<Refund | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleFetch = async () => {
    setErrorMessage(null);
    setSuccessMessage(null);

    if (!refundId.trim()) {
      setErrorMessage('환불 ID를 입력해 주세요.');
      return;
    }

    if (!isReasonValid) {
      setErrorMessage('조회 사유를 5자 이상 입력해 주세요.');
      return;
    }

    setIsLoading(true);
    try {
      const data = await getRefund(refundId.trim(), reason.trim());
      setRefund(data);
    } catch (err: unknown) {
      setRefund(null);
      if (err instanceof Error) {
        setErrorMessage(err.message);
      } else {
        setErrorMessage('환불 정보를 불러오는 중 오류가 발생했습니다.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleApprove = async () => {
    if (!refund) return;
    setErrorMessage(null);
    setSuccessMessage(null);

    if (!isReasonValid) {
      setErrorMessage('변경 사유를 5자 이상 입력해 주세요.');
      return;
    }

    setIsUpdating(true);
    try {
      const updated = await updateRefundStatus(refund.id, 'approved', reason.trim());
      setRefund(updated);
      setSuccessMessage('환불이 성공적으로 승인되었습니다. (status: approved)');
    } catch (err: unknown) {
      if (err instanceof Error) {
        setErrorMessage(err.message);
      } else {
        setErrorMessage('환불 승인 처리 중 오류가 발생했습니다.');
      }
    } finally {
      setIsUpdating(false);
    }
  };

  return (
    <main style={{ maxWidth: '800px', margin: '32px auto', padding: '0 20px', fontFamily: 'system-ui, -apple-system, sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 700, margin: '0 0 8px 0', color: '#111827' }}>
          환불 상태 변경 어드민
        </h1>
        <p style={{ margin: 0, color: '#6b7280', fontSize: '14px' }}>
          환불 ID와 조회 사유를 입력하여 조회하고 상태를 승인(approved)할 수 있습니다.
        </p>
      </header>

      <section style={{ backgroundColor: '#f9fafb', border: '1px solid #e5e7eb', borderRadius: '8px', padding: '20px', marginBottom: '20px' }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <div>
            <TextField
              label="환불 ID"
              value={refundId}
              onChange={(e) => setRefundId(e.target.value)}
              placeholder="예: R001"
            />
          </div>

          <div>
            <TextField
              label="사유 (5자 이상 필수)"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="사유를 5자 이상 입력하세요"
            />
            {!isReasonValid && (
              <p style={{ margin: '4px 0 0 0', color: '#dc2626', fontSize: '12px' }}>
                사유는 5자 이상 입력해야 합니다. (현재: {reason.trim().length}자)
              </p>
            )}
          </div>

          <div>
            <Button
              type="button"
              onClick={handleFetch}
              disabled={isLoading || isUpdating || !isReasonValid}
              style={{
                padding: '8px 20px',
                backgroundColor: '#1f2937',
                color: '#ffffff',
                border: 'none',
                borderRadius: '6px',
                cursor: (isLoading || isUpdating || !isReasonValid) ? 'not-allowed' : 'pointer',
                opacity: (isLoading || isUpdating || !isReasonValid) ? 0.6 : 1,
                fontSize: '14px',
                fontWeight: 500,
              }}
            >
              {isLoading ? '조회 중...' : '조회'}
            </Button>
          </div>
        </div>
      </section>

      {errorMessage && (
        <div style={{ padding: '12px 16px', backgroundColor: '#fef2f2', border: '1px solid #f87171', borderRadius: '6px', color: '#991b1b', marginBottom: '20px', fontSize: '14px' }}>
          {errorMessage}
        </div>
      )}

      {successMessage && (
        <div style={{ padding: '12px 16px', backgroundColor: '#f0fdf4', border: '1px solid #86efac', borderRadius: '6px', color: '#166534', marginBottom: '20px', fontSize: '14px' }}>
          {successMessage}
        </div>
      )}

      {refund && (
        <section style={{ backgroundColor: '#ffffff', border: '1px solid #e5e7eb', borderRadius: '8px', padding: '20px', boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
          <h2 style={{ fontSize: '18px', fontWeight: 600, margin: '0 0 16px 0', color: '#111827' }}>
            환불 상세 내역
          </h2>

          <div style={{ marginBottom: '20px' }}>
            <Table
              columns={[
                { key: 'id', header: 'id' },
                { key: 'amount', header: 'amount' },
                { key: 'status', header: 'status' },
