import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Refund {
  id: string;
  orderId?: string;
  amount: number;
  reason?: string;
  status: 'requested' | 'approved' | 'rejected' | string;
  [key: string]: unknown;
}

export async function getRefund(id: string, reason: string): Promise<Refund> {
  const response = await toiFetch('refunds', `/refunds/${encodeURIComponent(id)}`, {
    reason,
  });

  if (!response.ok) {
    const errData = await response.json().catch(() => null);
    if (response.status === 404 && errData?.code === 'PROJECT_NOT_FOUND') {
      throw new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
    }
    if (response.status === 404) {
      throw new Error('해당 환불 내역을 찾을 수 없습니다.');
    }
    throw new Error(errData?.message || `환불 조회에 실패했습니다. (HTTP ${response.status})`);
  }

  return response.json();
}

export async function updateRefundStatus(
  id: string,
  status: 'requested' | 'approved' | 'rejected',
  reason: string
): Promise<Refund> {
  const response = await toiFetch('refunds', `/refunds/${encodeURIComponent(id)}`, {
    method: 'PATCH',
    reason,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  });

  if (!response.ok) {
    const errData = await response.json().catch(() => null);
    if (response.status === 404 && errData?.code === 'PROJECT_NOT_FOUND') {
      throw new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
    }
    throw new Error(errData?.message || `환불 상태 변경에 실패했습니다. (HTTP ${response.status})`);
  }

  return response.json();
}

