  const [reason, setReason] = useState('직원 정보 조회');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isValidReason = reason.trim().length >= 5;

  const handleSearch = async () => {
    if (!isValidReason) {
      setError('조회 사유를 5자 이상 입력해 주세요.');
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const data = await listEmployees(reason.trim());
      setEmployees(data);
    } catch (err: any) {
      if (
        err?.code === 'PROJECT_NOT_FOUND' ||
        err?.name === 'ToiAccessRevokedError' ||
        (typeof err?.message === 'string' && err.message.includes('이 프로젝트에 접근할 수 없어요')) ||
        (typeof err?.message === 'string' && err.message.includes('PROJECT_NOT_FOUND'))
      ) {
