            borderRadius: '4px',
            marginBottom: '16px',
          }}
        >
          {error}
        </div>
      )}

      {!isAccessRevoked && (
        <Table<Order> columns={columns} rows={rows} rowKey="id" />
      )}
    </main>
  );
}

