import { configureToiFetch, toiFetch } from '@toi/fetch';

type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Employee extends Record<string, unknown> {
  id: string;
  name: string;
  phone: string;
  email: string;
  rrn: string;
  account: string;
  department?: string;
  status?: string;
}

export async function listEmployees(reason: string): Promise<{ items: Employee[] }> {
  let response: Response;
  try {
    response = await toiFetch('employees', '/employees', { reason });
  } catch (err: any) {
    if (
      (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
      err?.name === 'ToiAccessRevokedError' ||
      err?.message?.includes('PROJECT_NOT_FOUND')
    ) {
      throw new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
    }
    throw err;
  }

  if (!response.ok) {
    let errorData: any = null;
    try {
      errorData = await response.json();
    } catch {
      // ignore json parse error
    }
    if (response.status === 404) {
      if (errorData?.code === 'PROJECT_NOT_FOUND') {
        throw new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      }
      return { items: [] };
    }
    throw new Error(errorData?.message || `조회 실패 (${response.status})`);
  }

  return response.json();
}

import { useState } from 'react';
import { Button, TextField, Table } from '@toi/tds';
import { listEmployees, Employee } from './api';

export default function App() {
  const [reason, setReason] = useState('');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [hasSearched, setHasSearched] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const isReasonValid = reason.trim().length >= 5;

  const handleSearch = async () => {
    if (!isReasonValid || loading) return;
    setLoading(true);
    setErrorMessage(null);
    try {
      const data = await listEmployees(reason.trim());
      setEmployees(data.items || []);
      setHasSearched(true);
    } catch (err: any) {
      if (
        (err?.status === 404 && err?.code === 'PROJECT_NOT_FOUND') ||
        err?.message?.includes('PROJECT_NOT_FOUND') ||
        err?.name === 'ToiAccessRevokedError'
      ) {
        setErrorMessage('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else {
        setErrorMessage(err?.message || '조회 중 오류가 발생했습니다.');
      }
    } finally {
      setLoading(false);
    }
  };

  const columns = [
    { key: 'id', header: 'id' },
    { key: 'name', header: 'name' },
    { key: 'phone', header: 'phone' },
    { key: 'email', header: 'email' },
    { key: 'rrn', header: 'rrn' },
    { key: 'account', header: 'account' },
  ];

  return (
    <main style={{ padding: '24px', maxWidth: '1000px', margin: '0 auto', fontFamily: 'sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '22px', fontWeight: 'bold', margin: '0 0 8px 0' }}>직원 목록 조회</h1>
        <p style={{ margin: 0, color: '#666', fontSize: '14px' }}>
          직원 정보 조회를 위해 5자 이상의 사유를 입력해 주세요.
        </p>
      </header>

      <section style={{ display: 'flex', gap: '12px', alignItems: 'flex-start', marginBottom: '24px' }}>
        <div style={{ flex: 1, maxWidth: '400px' }}>
          <TextField
            label="조회 사유"
            placeholder="조회 사유를 5자 이상 입력하세요"
            value={reason}
            onChange={(e) => setReason(e.target.value)}
          />
          {reason.length > 0 && !isReasonValid && (
            <p style={{ color: '#e53e3e', fontSize: '12px', margin: '4px 0 0 0' }}>
              사유는 최소 5자 이상 입력해야 합니다. (현재 {reason.trim().length}자)
            </p>
          )}
        </div>
        <div style={{ marginTop: '24px' }}>
          <Button
            type="button"
            onClick={handleSearch}
            disabled={!isReasonValid || loading}
          >
            {loading ? '조회 중...' : '조회'}
          </Button>
        </div>
      </section>

      {errorMessage && (
        <div
          role="alert"
          style={{
            padding: '12px 16px',
            backgroundColor: '#fff5f5',
            color: '#c53030',
            borderRadius: '6px',
            marginBottom: '20px',
            border: '1px solid #feb2b2',
            fontSize: '14px',
          }}
        >
          {errorMessage}
        </div>
      )}

      {hasSearched && !errorMessage && (
        <section>
          <div style={{ marginBottom: '12px', fontSize: '14px', color: '#555' }}>
            총 {employees.length}명
          </div>
          <Table columns={columns} rows={employees} rowKey="id" />
        </section>
      )}
    </main>
  );
}

