import { configureToiFetch, toiFetch } from '@toi/fetch';

// The trusted preview host provides credential-free broker routing.
type HostConfig = Parameters<typeof configureToiFetch>[0];
const hostConfig = (globalThis as typeof globalThis & { __TOI_FETCH_CONFIG__?: HostConfig }).__TOI_FETCH_CONFIG__;
if (!hostConfig) throw new Error('Preview host configuration missing: __TOI_FETCH_CONFIG__');
configureToiFetch(hostConfig);

export interface Customer extends Record<string, unknown> {
  id: string;
  name: string;
  phone: string;
  status: string;
  email?: string;
}

export async function listRecords(reason: string) {
  const response = await toiFetch('customers', '/customers', { reason });
  const data = await response.json().catch(() => null);

  if (!response.ok) {
    if (response.status === 404) {
      if (data?.code === 'PROJECT_NOT_FOUND' || data?.error?.code === 'PROJECT_NOT_FOUND') {
        const err = new Error('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
        (err as unknown as { code: string }).code = 'PROJECT_NOT_FOUND';
        throw err;
      }
      return { items: [] };
    }
    throw new Error(data?.message || data?.error?.message || '고객 목록을 조회하지 못했습니다.');
  }

  return data;
}

export async function getRecord(id: string, reason: string) {
  const response = await toiFetch('customers', '/customers/' + encodeURIComponent(id), { reason });
  return response.json();
}

export async function updateStatus(id: string, status: 'active' | 'inactive' | 'suspended', reason: string) {
  const response = await toiFetch('customers', '/customers/' + encodeURIComponent(id), {
    method: 'PATCH',
    reason,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status }),
  });
  return response.json();
}

import { useState } from 'react';
import { Button, TextField, Table } from '@toi/tds';
import { listRecords, Customer } from './api';

export default function App() {
  const [reason, setReason] = useState('');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasSearched, setHasSearched] = useState(false);

  const isValidReason = reason.trim().length >= 5;

  const handleSearch = async () => {
    const trimmedReason = reason.trim();
    if (trimmedReason.length < 5) {
      setError('조회 사유를 5자 이상 입력해 주세요.');
      return;
    }

    try {
      setLoading(true);
      setError(null);
      const data = await listRecords(trimmedReason);
      const items: Customer[] = Array.isArray(data)
        ? data
        : Array.isArray(data?.items)
        ? data.items
        : [];

      const sanitized: Customer[] = items.map((item) => ({
        id: String(item.id ?? ''),
        name: String(item.name ?? ''),
        phone: String(item.phone ?? ''),
        status: String(item.status ?? ''),
      }));

      setCustomers(sanitized);
      setHasSearched(true);
    } catch (err: unknown) {
      const e = err as Error & { code?: string };
      if (e?.code === 'PROJECT_NOT_FOUND' || e?.message?.includes('이 프로젝트에 접근할 수 없어요')) {
        setError('이 프로젝트에 접근할 수 없어요. 멤버에서 제거되었거나 권한이 바뀌었을 수 있어요');
      } else {
        setError(e?.message || '고객 목록을 조회하는 중 오류가 발생했습니다.');
      }
    } finally {
      setLoading(false);
    }
  };

  const columns = [
    { key: 'id' as const, header: 'id' },
    { key: 'name' as const, header: 'name' },
    { key: 'phone' as const, header: 'phone' },
    { key: 'status' as const, header: 'status' },
  ];

  return (
    <div style={{ padding: '24px', maxWidth: '1000px', margin: '0 auto', fontFamily: 'sans-serif' }}>
      <header style={{ marginBottom: '24px' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 600, margin: '0 0 8px 0' }}>고객 목록</h1>
        <p style={{ margin: 0, color: '#666', fontSize: '14px' }}>
          고객 정보를 조회하려면 조회 사유를 5자 이상 입력하세요.
        </p>
      </header>

      <section
        style={{
          display: 'flex',
          gap: '12px',
          alignItems: 'flex-end',
          marginBottom: '20px',
          flexWrap: 'wrap',
        }}
      >
        <div style={{ flex: '1 1 320px' }}>
          <TextField
            label="조회 사유"
            placeholder="조회 사유를 5자 이상 입력하세요"
            value={reason}
            onChange={(e) => {
              setReason(e.target.value);
              if (error) setError(null);
            }}
          />
        </div>
        <Button
          type="button"
          onClick={handleSearch}
          disabled={loading || !isValidReason}
        >
          조회
        </Button>
      </section>

      {reason.length > 0 && !isValidReason && (
        <p style={{ color: '#d32f2f', fontSize: '13px', marginTop: '-12px', marginBottom: '16px' }}>
          조회 사유는 최소 5자 이상 입력해야 합니다. (현재 {reason.trim().length}자)
        </p>
      )}

      {error && (
        <div
          role="alert"
          style={{
            padding: '12px 16px',
            backgroundColor: '#fee2e2',
            border: '1px solid #fca5a5',
            borderRadius: '6px',
            color: '#b91c1c',
            marginBottom: '20px',
            fontSize: '14px',
          }}
        >
          {error}
        </div>
      )}

      {loading && (
        <div style={{ padding: '24px', textAlign: 'center', color: '#666' }}>
          고객 목록을 조회 중입니다...
        </div>
      )}

      <Table<Customer>
        columns={columns}
        rows={customers}
        rowKey="id"
      />

      {hasSearched && !loading && customers.length === 0 && !error && (
        <div style={{ padding: '24px', textAlign: 'center', color: '#888' }}>
          조회된 고객이 없습니다.
        </div>
      )}
    </div>
  );
}

